// T046: Snippets.generated.cs (executable code samples) - Blazorise pattern.
// P1, 24h, depends T021 (Docs.Compiler) - generator runs at build time.
namespace XForge.DesignSystem.Generators.Snippets;

/// <summary>
/// Immutable snippet record. Generated by the Roslyn source generator and embedded as <c>Snippets.generated.cs</c>.
/// </summary>
public sealed record XFSnippet(
    string Component,
    string Title,
    string Code,
    string? Description = null,
    string Language = "razor",
    IReadOnlyList<string>? Tags = null)
{
    /// <summary>Renders the snippet as a fenced markdown block.</summary>
    public string ToMarkdown() => $"### {Title}`n`n```{Language}`n{Code}`n```";
}

/// <summary>Registry of generated snippets. Populated by the source generator.</summary>
public static class XFSnippetCatalog
{
    public static IReadOnlyList<XFSnippet> All { get; } = new List<XFSnippet>
    {
        new("XButton", "Basic Button", "<XButton>Click me</XButton>", "Primary action button.", "razor", new[] { "buttons", "basic" }),
        new("XButton", "Outline Button", "<XButton Outline=\"true\">Cancel</XButton>", "Secondary action.", "razor", new[] { "buttons", "outline" }),
        new("XInput", "Bound Input", "<XInput @bind-Value=\"Name\" />", "Two-way bound text input.", "razor", new[] { "forms" }),
        new("XCard", "Simple Card", "<XCard Title=\"Hello\">Body</XCard>", "Card with title.", "razor", new[] { "layout" }),
        new("XModal", "Open Modal", "<XModal @ref=\"_m\"><XButton OnClick=\"@(() => _m.Show())\">Open</XButton></XModal>", "Show/hide modal.", "razor", new[] { "overlays" }),
    };

    public static IEnumerable<XFSnippet> ForComponent(string component) => All.Where(s => s.Component == component);
}

/// <summary>Generator interface (would be backed by ISourceGenerator in production).</summary>
public interface IXFSnippetsGenerator
{
    /// <summary>Generates the <c>Snippets.generated.cs</c> source string.</summary>
    string Generate();
    /// <summary>Returns the count of snippets the generator will emit.</summary>
    int Count { get; }
}

/// <summary>Default generator that emits <see cref="XFSnippetCatalog.All"/>.</summary>
public sealed class XFDefaultSnippetsGenerator : IXFSnippetsGenerator
{
    public int Count => XFSnippetCatalog.All.Count;
    public string Generate()
    {
        var sb = new System.Text.StringBuilder();
        sb.AppendLine("// <auto-generated/> by XFSnippetsGenerator (T046).");
        sb.AppendLine("namespace XForge.DesignSystem.Generated;");
        sb.AppendLine("public static class Snippets");
        sb.AppendLine("{");
        foreach (var s in XFSnippetCatalog.All) sb.AppendLine($"    /// <summary>Snippet for {s.Component}: {s.Title}</summary>").AppendLine($"    public const string {s.Component}_{s.Title.Replace(" ", "_")} = @\"{s.Code}\";");
        sb.AppendLine("}");
        return sb.ToString();
    }
}